function trim(s) {
  return s.trim();
}

function slugify(s) {
  return s
    .normalize('NFD')
    // drop combining marks so accented Latin folds to ASCII (é -> e)
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { trim, slugify };

test('slugify folds accented Latin to ASCII rather than dropping it', () => {
  assert.strictEqual(slugify('café'), 'cafe');
  assert.strictEqual(slugify('Naïve Café'), 'naive-cafe');
  assert.strictEqual(slugify('Ñandú'), 'nandu');
});

